--  O la fecha de nacimiento no está insertada y es null, o si aparece, tiene que ser anterior al día de hoy

ALTER TABLE PERSONA 
ADD CONSTRAINT chk_fecha_nacimiento_rango 
CHECK (fecha_nacimiento IS NULL OR fecha_nacimiento <'2026-01-01');

-- "fecha_construccion" de SEDE_CANONICA a tipo DATE

ALTER TABLE SEDE_CANONICA 
MODIFY fecha_construccion DATE;

-- En EPOCA_HISTORICA, cambiar "fechas" a NOT NULL

ALTER TABLE EPOCA_HISTORICA 
MODIFY fechas VARCHAR(45) NOT NULL;

-- Cambiar "tiempo_en_calle" de HERMANDAD_PROCESIONAL a INT que necesariamente tiene que ser 
-- mayor a 0

ALTER TABLE HERMANDAD_PROCESIONAL 
MODIFY tiempo_en_calle INT NOT NULL,
ADD CONSTRAINT tiempo_positivo CHECK (tiempo_en_calle > 0);

-- Modificar la tabla HERMANDAD_PROCESIONAL de manera que, por ser hija de HERMANDAD, cuando se elimine o actualice un registro en el padre,
-- ocurra lo mismo en la hija.

ALTER TABLE HERMANDAD_PROCESIONAL
DROP CONSTRAINT fk_nombre_hdad_procesional;
ALTER TABLE HERMANDAD_PROCESIONAL
ADD CONSTRAINT fk_hdad_procesional_nueva 
FOREIGN KEY (nombre_hdad_procesional) 
REFERENCES HERMANDAD (nombre) 
ON DELETE CASCADE 
ON UPDATE CASCADE;

-- Modificar la tabla SEDE_CANONICA para quedarnos solo con el año de construcción

ALTER TABLE SEDE_CANONICA
MODIFY fecha_construccion SMALLINT;

-- Añadir una nueva columna a la tabla PROCESION llamada numero_pasos, que contendrá el número de pasos que componen la procesión. Habrá
-- de ser un natural mayor a 0

ALTER TABLE PROCESION 
ADD COLUMN numero_pasos INT CHECK (numero_pasos > 0);

