SET SQL_SAFE_UPDATES = 0;

update SEDE_CANONICA
set estilo_arquitectonico_predominante = if(estilo_arquitectonico_predominante = '', 'Estilo no definido', estilo_arquitectonico_predominante)
where estilo_arquitectonico_predominante = '';

SET SQL_SAFE_UPDATES = 1; -- Esto se realiza por que no puedo actualizar registros que no utilicen la PK en WHERE.

-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- --------------------------------------------------------------  Consultas  ------------------------------------------------------------------
-- ---------------------------------------------------------------------------------------------------------------------------------------------

-- Devolver el nombre de todas aquellas hermandades con nombre coloquial cuyo nombre oficial comience por "la" o cuyo nombre coloquial termine por "la"
-- y ordenar alfabéticamente por nombre oficial.

select nombre_oficial
from nombre_coloquial
where nombre_oficial like 'La%' or nombre_coloquial like '%la'
order by nombre_oficial;

-- Para hermandades que hayan residido previamente en otra/s sede/s distinta/s, devolver todos los datos solo si la cuota anual está entre 45 y 50, ambos 
-- inclusive. Ordenar por cuota anual ascendentemente y por año fundacional descendentemente

select *
from hermandad inner join residia_en on hermandad.nombre = residia_en.nombre_hdad
where cuota_anual between 45 and 50
order by cuota_anual asc,año_fundacional;

-- Devolver los registros de HERMANDAD cuyo número de hermanos no sea
-- superado por ninguna otra hermandad.

select *
from hermandad
where nombre in (select nombre_hdad_es_hermano 
                 from es_hermano_de
                 group by nombre_hdad_es_hermano
                 having count(*) = (select count(*) 
                                    from es_hermano_de 
                                    group by nombre_hdad_es_hermano 
                                    order by 1 desc 
                                    limit 1));
                
-- Número de roles distintos participantes en cada día de Semana Santa o estival, limitándonos solo a aquellas jornadas con más de 3 personas

select dia_SS_estival, count(distinct rol_participacion) as roles_distintos, count(dni_persona_participante) as total_personas
from participa
group by dia_SS_estival
having total_personas > 3;

-- Cómputo del importe por papeleta por día de Semana Santa o día estival

select dia_SS_estival,sum(importe_papeleta_sitio) as Cómputo_papeletas
from dia_procesional natural join participa
group by dia_SS_estival;

-- Devolver los datos de las personas que son hermanas de alguna hermandad y que no participan en ninguna procesión

select *
from persona p inner join es_hermano_de e on p.dni = e.dni_hermano
where dni not in (select dni_persona_participante from participa);

-- Devolver los datos de los datos de la tabla participa para las personas que salgan en procesión extraordinaria y cuyo rol sea o acólito
-- o nazareno, ordenados los registros por el importe de papeleta descendentemente

select *
from participa
where motivo_procesion in (select motivo from procesion where extraordinariedad = 'Sí') and rol_participacion in ("Acólito","Nazareno")
order by importe_papeleta_sitio desc;

-- Devolver la fecha de construcción y la dirección de la sede canónica, para aquellas donde el estilo arquitectonico predominante sea 
-- el gótico o un subgénero de este. En fechas donde no haya registro, mostrar "No se conoce"

select direccion, coalesce(fecha_construccion,"No se conoce") as fecha_construccion
from sede_canonica
where estilo_arquitectonico_predominante like "%Gótico%";

-- Para las hermandades, clasificar la cantidad de cuota anual en "precio bajo" si son menores o iguales a 40;"precio medio" si están entre 40 y
-- 60; y "precio alto" si son mayores o iguales a 60. Devolver, por tanto, nombre de las hermandades y precio de las cuotas anuales y ordernar 
-- alfabéticamente por nombre

select nombre, cuota_anual,
    case 
        when cuota_anual <= 40 then 'precio bajo' 
        when cuota_anual >= 60 then 'precio alto' 
        else'precio medio' 
    end as coste_cuotas
from hermandad
order by nombre;

-- Devolver nombre de hermandades procesionales de menos de 10 horas junto con comunidades históricas con las que han coexistido a lo largo 
-- del tiempo, así como el nombre que le daban a la ciudad de Sevilla y cada origen etimológico.

select h2.nombre,comunidad_ciudad,nombre_ciudad,tipo_fuente,etimologia
from hermandad_procesional h1 inner join  hermandad h2 on h1.nombre_hdad_procesional = h2.nombre
inner join sede_canonica s on h2.direccion_sede = s.direccion
inner join desarrollo_durante d on s.direccion = d.direccion_sede
inner join epoca_historica e on d.periodo_epoca = e.periodo
inner join nomenclatura_ciudad n using(periodo)
inner join detalle_nomenclatura d1 on n.nombre = d1.nombre_ciudad and n.comunidad = d1.comunidad_ciudad
where tiempo_en_calle<10;

-- Devolver nombre de hermandades procesionales que impliquen todos los roles menos 'Músico' y 'Monaguillo'

select h1.nombre_hdad_procesional as Nombre  
from implica i inner join hermandad h on i.nombre_hdad_implicada = h.nombre 
inner join hermandad_procesional h1 on h.nombre = h1.nombre_hdad_procesional
where categoria_rol not in ('Músico','Monaguillo')
group by nombre_hdad_procesional
having count(distinct i.categoria_rol) = (select count(distinct categoria) from rol  where categoria not in ('Músico','Monaguillo'));

-- Datos de aquellas sedes para las cuales no existe ninguna nomenclatura de la ciudad que no esté vinculada a dicha sede a través de su 
-- periodo histórico

select *
from sede_canonica s
where not exists (select *
                  from nomenclatura_ciudad n
                  where not exists (select *
									from desarrollo_durante d
                                    where d.direccion_sede = s.direccion and d.periodo_epoca = n.periodo));
                                    
-- Devolver la fecha de nacimiento de aquellas personas que hayan nacido después de alguna de las personas cuyo DNI termina en A

select fecha_nacimiento
from persona
where year(fecha_nacimiento) > any (select year(fecha_nacimiento) from persona where dni like '%A');

-- Construye una vista para recopilar información de una hermandad, su sede y su nombre coloquial y devuelve datos para el estilo barroco

create view vista_resumen_hermandades as
select h.nombre as nombre_oficial, nc.nombre_coloquial, h.año_fundacional, s.direccion as sede, s.estilo_arquitectonico_predominante as estilo
from hermandad h inner join nombre_coloquial nc on h.nombre = nc.nombre_oficial inner join sede_canonica s on h.direccion_sede = s.direccion;

select *
from vista_resumen_hermandades
where estilo = 'Barroco';

-- Clasifica en una nueva columna la naturaleza de los pueblos que dieron diversas nomenclaturas a Sevilla, según si fueron antes o después
-- de los romanos.

select *,
if( comunidad_ciudad like '%fenicia%' or comunidad_ciudad like '%tartesia%','Pueblos prerromanos','Pueblos posromanos') 
as naturaleza_comunidad
from detalle_nomenclatura;